use crate::openapi::{Context, Operation, Response, rust_field};
use std::fmt::Write as _;

pub fn generate(context: &Context<'_>, operations: &[Operation]) -> Result<String, String> {
    let mut output = String::from(
        "//! One live test per documented top-level collection: each reads the\n//! first item through the resource layer and decodes it through the typed\n//! models.\n//!\n//! This file is generated by `cargo xtask update-openapi`.\n\nuse super::live_client;\nuse std::fmt::Debug;\n\nfn check<T: Debug>(operation: &str, result: rentman_client::Result<Vec<T>>) {\n    if let Err(error) = result {\n        panic!(\"{operation} failed against the live API: {error:#}\");\n    }\n}\n\n",
    );
    for operation in operations.iter().filter(|op| {
        op.method == "GET"
            && matches!(op.response, Response::Collection(_))
            && !op.parameters.iter().any(|p| p.location == "Path")
    }) {
        let collection = operation.path.trim_matches('/');
        let resource = context.resource_for_collection(collection, &operation.path)?;
        writeln!(output, "#[tokio::test]\n#[cfg_attr(\n    not(live_api_tests_enabled),\n    ignore = \"calls the real Rentman API; requires RENTMAN_API_TOKEN\"\n)]\nasync fn {}() {{\n    check(\"{}\", live_client().{}().list().first(1).await);\n}}\n",
            rust_field(&operation.operation_id), operation.operation_id, accessor_name(resource)).unwrap();
    }
    Ok(output)
}

pub fn accessor_name(resource: &str) -> String {
    let name = rust_field(resource);
    let uncountable = crate::openapi::config()
        .uncountable_types
        .iter()
        .any(|value| value == resource);
    if uncountable {
        return name;
    }
    if name.ends_with('y')
        && name
            .chars()
            .rev()
            .nth(1)
            .is_some_and(|ch| !"aeiou".contains(ch))
    {
        return format!("{}ies", &name[..name.len() - 1]);
    }
    if ["s", "x", "ch", "sh"]
        .iter()
        .any(|suffix| name.ends_with(suffix))
    {
        return format!("{name}es");
    }
    format!("{name}s")
}

#[cfg(test)]
// Coverage is disabled for test code so the production 100% gate measures only
// generator behavior.
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;
    use crate::test_support::{context, spec};

    #[test]
    fn sweeps_every_top_level_collection() {
        let spec = spec();
        let (context, operations) = context(&spec).unwrap();
        let sweep = generate(&context, &operations).unwrap();
        assert!(sweep.contains("async fn get_widget_collection() {\n    check(\"getWidgetCollection\", live_client().widgets().list().first(1).await);"));
        assert!(sweep.contains("live_client().parts()"));
        assert!(!sweep.contains("getWidgetPartCollection"));
    }

    #[test]
    fn accessors_are_english_plurals() {
        for (resource, accessor) in [
            ("TaskStatus", "task_statuses"),
            ("Factory", "factories"),
            ("Day", "days"),
            ("Box", "boxes"),
            ("Batch", "batches"),
            ("Wish", "wishes"),
            ("Widget", "widgets"),
            ("Crew", "crew"),
        ] {
            assert_eq!(accessor_name(resource), accessor);
        }
    }
}
